/* eslint-disable @next/next/no-img-element --
 * These are Supabase public URLs on a host `next/image` is not configured for,
 * and every one was generated by the pipeline at the exact pixel size of the
 * box it fills. There is nothing left for the optimiser to do, and routing
 * them through it would add a hop and a remotePatterns entry per project.
 */
import {
  EASING_CURVES,
  ORIGIN_POSITIONS,
  isAnimated,
  motionFrames,
  type Motion,
} from '@agents/motion';
import { ARCHETYPE_GRIDS } from '@agents/pptx/archetype-grid';
import type { LayoutArchetype } from '@agents/pptx/layouts';
import { contains, overlaps } from '@agents/pptx/positioning';
import { placementFor, shrinkToFit, type VAlign } from '@agents/pptx/theme';
import {
  MIN_TYPE_SIZES,
  TEXT_SCRIM_OPACITY,
  fontStack,
  readableOn,
  type PPTXTheme,
} from '@agents/pptx/theme-resolve';
import type { SlideBlock } from '@/lib/slides/blocks';

/**
 * One slide, drawn in the browser.
 *
 * This is the web half of `Agents/pptx/builder.ts`, and the two share their
 * rules rather than reimplementing them: `placementFor` decides alignment,
 * `readableOn` decides text colour against whatever is behind it, and both are
 * imported from the same module the builder uses. A preview that composes a
 * slide differently from the file the user downloads is worse than no preview
 * — it teaches them to distrust it.
 *
 * ## Scaling
 *
 * The pipeline works in inches on a canvas the StyleSpec fixes (13.333 x 7.5).
 * Positions are therefore percentages of that canvas, which are resolution-
 * independent for free. Type sizes are the awkward part: a 44pt title has to
 * shrink with the slide, or a thumbnail renders one enormous word.
 *
 * So the slide is a **container** and every font size is in `cqw` — 1% of the
 * slide's own width. A point is 1/72 inch, and the canvas is `slideSize.width`
 * inches wide, so `pt -> cqw` is `(pt / 72 / width) * 100`. One component then
 * renders correctly at 1200px in the viewer and at 200px as a card thumbnail,
 * with no size prop and no second code path.
 *
 * ## `viewportMode`
 *
 * `Agents/pptx/browser-layout.ts` renders this same component into a headless
 * browser at a fixed pixel viewport to MEASURE it — `getBoundingClientRect()`
 * and an in-page shrink-to-fit loop, whose output becomes the `box`/`fontSize`
 * the .pptx builder draws. `cqw` is meaningless off-DOM-tree in that context
 * (there is no ancestor container to query against the way the live app's
 * layout provides one), so `viewportMode: 'export'` switches every size to
 * literal `px` at a fixed pixels-per-inch, using the exact same `pt`/`inches`
 * formulas with a different unit. `viewportMode: 'live'` (the default) is
 * this component's original, unchanged behaviour. Same JSX, same theme rules,
 * one branch in the unit helpers below — not a second template.
 *
 * ## `archetype` and grid placement
 *
 * In export mode, a slide carrying an `archetype` its elements have `slot`s
 * for is laid out with a real CSS Grid (`Agents/pptx/archetype-grid.ts`)
 * instead of the absolute `box` percentages every other slide (and every
 * *unslotted* element, even on an archetype slide) still uses. This is the
 * headless-browser replacement for `Agents/pptx/layouts.ts`'s `slotsFor`: a
 * grid cell cannot overlap another named area, so a heading and a picture
 * placed in `title` and `image` areas cannot end up on top of each other —
 * not because a check ran afterwards and passed, but because there is no
 * arrangement of a valid CSS Grid where that happens. Row heights are `auto`,
 * so a title gets exactly the room its real, wrapped text needs instead of a
 * two-lines'-worth guess made before anyone knew what the title said.
 */

/** CSS px per inch used only in `viewportMode: 'export'`, for a fixed-size headless render. */
const EXPORT_PIXELS_PER_INCH = 96;

export interface RenderableSlide {
  title: string | null;
  subtitle: string | null;
  blocks: SlideBlock[];
  backgroundUrl: string | null;
  /** 0-1. How far the backdrop is faded toward the background colour. */
  backgroundDim: number;
  /**
   * The slide's layout archetype, if it has one. Only consulted in
   * `viewportMode: 'export'` — see the header comment on grid placement.
   */
  archetype?: LayoutArchetype | null;
}

export interface SlideCanvasProps {
  slide: RenderableSlide;
  theme: PPTXTheme;
  slideSize: { width: number; height: number };
  /** Decorative in a thumbnail strip; meaningful as the main stage. */
  className?: string;
  /**
   * `'live'` (default): sizes in `cqw`, for the app's own resizable preview.
   * `'export'`: sizes in fixed `px`, for a headless-browser measurement pass.
   * See the header comment.
   */
  viewportMode?: 'live' | 'export';
  /**
   * Play the elements' stored motion.
   *
   * Off by default, and forced off in `viewportMode: 'export'`: the headless
   * measuring pass reads `getBoundingClientRect()`, and a box caught mid-zoom
   * measures as whatever scale it happened to be at. The same reasoning keeps
   * it off in thumbnails, where six slides animating at once in a rail is
   * noise rather than information.
   *
   * Restarting the entrance is the caller's job — remount with a new `key`.
   * A CSS animation only runs once per element, so there is no way to replay
   * one without either a new element or a class dance, and a remount is the
   * honest version of that.
   */
  animate?: boolean;
}

/** Theme size for an element's semantic role. Mirrors `sizeForRole` in the builder. */
function sizeForRole(theme: PPTXTheme, role: string): number {
  switch (role) {
    case 'title':
      return theme.sizes.title;
    case 'subtitle':
      return theme.sizes.subtitle;
    case 'caption':
    case 'label':
      return theme.sizes.caption;
    default:
      return theme.sizes.body;
  }
}

function colorForRole(theme: PPTXTheme, role: string): string {
  if (role === 'caption' || role === 'label') return theme.colors.secondaryText;
  if (role === 'accent') return theme.colors.accent;
  return theme.colors.text;
}

function isHeading(role: string): boolean {
  return role === 'title' || role === 'subtitle';
}

/**
 * Legibility floor for this role, in points. Only consulted in `viewportMode:
 * 'export'`, where `Agents/pptx/browser-layout.ts`'s in-page shrink-to-fit
 * loop needs a hard lower bound — the same one `theme-resolve.ts` already
 * enforces on the StyleSpec's own sizes, applied per element this time.
 */
function minSizeForRole(role: string): number {
  switch (role) {
    case 'title':
      return MIN_TYPE_SIZES.title;
    case 'subtitle':
      return MIN_TYPE_SIZES.subtitle;
    case 'caption':
    case 'label':
      return MIN_TYPE_SIZES.caption;
    default:
      return MIN_TYPE_SIZES.body;
  }
}

/**
 * The attributes and custom properties that make one element move.
 *
 * All the arithmetic is `motionFrames` in `Agents/motion.ts`, shared with the
 * editor panel — a slider that computes a scale the renderer would not is a
 * control that lies. Everything here is presentational: no branch of this
 * touches the element's box, and returning `null` (thumbnail, export render,
 * an element left still) leaves the markup exactly as it was before motion
 * existed.
 */
function motionFor(
  motion: Motion | undefined,
  enabled: boolean,
): { attrs: Record<string, string>; style: React.CSSProperties } | null {
  if (!enabled || !isAnimated(motion)) return null;

  const { from, to, fadeFrom } = motionFrames(motion);

  return {
    attrs: { 'data-motion': motion.trigger },
    style: {
      transformOrigin: ORIGIN_POSITIONS[motion.origin],
      '--lm-from': String(from),
      '--lm-to': String(to),
      '--lm-fade': String(fadeFrom),
      '--lm-duration': `${motion.duration}s`,
      '--lm-delay': `${motion.delay}s`,
      '--lm-easing': EASING_CURVES[motion.easing],
    } as React.CSSProperties,
  };
}

/** `valign` as the flex property that produces it. */
const JUSTIFY: Record<VAlign, string> = {
  top: 'flex-start',
  middle: 'center',
  bottom: 'flex-end',
};

/**
 * What is behind this block. Mirrors `surfaceUnder` in the builder.
 *
 * A block inside a card sits on the surface colour, not the slide's; a slide
 * with a backdrop resolves to the background colour, which is what the scrim
 * blends the image toward.
 */
function surfaceUnder(block: SlideBlock, slide: RenderableSlide, theme: PPTXTheme): string {
  if (slide.backgroundUrl) return theme.colors.background;

  // Text over a picture is given a scrim of the background colour, which is
  // precisely so that this question has an answer. Mirrors the builder.
  if (overText(block, slide)) return theme.colors.background;

  const container = slide.blocks.find(
    (other) =>
      other !== block &&
      (other.type === 'card' || other.type === 'shape') &&
      contains(other.box, block.box),
  );

  return container ? (container.fill ?? theme.colors.surface) : theme.colors.background;
}

/** True when this block sits on top of a picture rather than on the slide. */
function overText(block: SlideBlock, slide: RenderableSlide): boolean {
  return slide.blocks.some(
    (other) => other !== block && other.type === 'image' && overlaps(other.box, block.box),
  );
}

/** `#rrggbb` at `alpha`, for the scrim behind text laid over a picture. */
function withAlpha(hex: string, alpha: number): string {
  const match = /^#?([0-9a-f]{6})$/i.exec(hex.trim());
  if (!match) return hex;

  const value = Number.parseInt(match[1], 16);
  return `rgba(${(value >> 16) & 255}, ${(value >> 8) & 255}, ${value & 255}, ${alpha})`;
}

/**
 * Stacking order. Mirrors `layer` in the builder.
 *
 * The browser has a z-index and PowerPoint does not, so the builder has to sort
 * before it draws. Sorting here too keeps the two in step for free.
 */
function layer(block: SlideBlock): number {
  if (block.type === 'image') return 0;
  if (block.type === 'card' || block.type === 'shape') return 1;
  return 2;
}

function Block({
  block,
  slide,
  theme,
  slideSize,
  viewportMode,
  elementId,
  gridArea,
  inStack = false,
  animate = false,
}: {
  block: SlideBlock;
  slide: RenderableSlide;
  theme: PPTXTheme;
  slideSize: { width: number; height: number };
  viewportMode: 'live' | 'export';
  elementId: number;
  /**
   * Set only for a slotted element on an archetype slide in export mode.
   * Positions the element by CSS Grid area instead of the absolute `box`
   * percentages — see the header comment.
   */
  gridArea?: string;
  /**
   * One of several elements sharing a slot, laid out in a flex column that
   * owns the grid area between them. It flows in that column rather than
   * claiming a cell of its own — two children of the same grid area occupy
   * the *same* cell, which is an overlap, not a stack.
   */
  inStack?: boolean;
  /** Draw this element's stored motion. Off everywhere but the live stage. */
  animate?: boolean;
}) {
  const { box } = block;
  const motion = motionFor(block.motion, animate);

  // Percentages of the canvas: the same numbers the .pptx uses, expressed as
  // fractions rather than inches. Works identically in both viewport modes —
  // only the FONT-size units differ (see the header comment). A grid-placed
  // element skips this entirely: its position and size come from the grid
  // cell it was assigned, which is exactly the point — that cell cannot
  // overlap a sibling's, where two independently-computed `box` rectangles
  // could.
  const frame: React.CSSProperties = inStack
    ? { width: '100%' }
    : gridArea
      ? { gridArea, width: '100%', height: '100%' }
      : {
          position: 'absolute',
          left: `${(box.x / slideSize.width) * 100}%`,
          top: `${(box.y / slideSize.height) * 100}%`,
          width: `${(box.w / slideSize.width) * 100}%`,
          height: `${(box.h / slideSize.height) * 100}%`,
        };

  /** Points to container-width (live) or fixed-px (export) units — see the header. */
  const pt = (points: number) =>
    viewportMode === 'export'
      ? `${(points / 72) * EXPORT_PIXELS_PER_INCH}px`
      : `${(points / 72 / slideSize.width) * 100}cqw`;
  const inches = (value: number) =>
    viewportMode === 'export'
      ? `${value * EXPORT_PIXELS_PER_INCH}px`
      : `${(value / slideSize.width) * 100}cqw`;

  const fallback = placementFor(block.type, block.role, {
    text: block.text,
    items: block.items,
  });
  const align = block.align ?? fallback.align;
  const valign = block.valign ?? fallback.valign;

  const behind =
    block.type === 'card' || block.type === 'shape'
      ? (block.fill ?? theme.colors.surface)
      : surfaceUnder(block, slide, theme);

  // The size the pipeline measured against the real font file, which the
  // .pptx builder draws too — so the two break lines in the same places rather
  // than in places that happen to agree. The estimate is the fallback for a
  // deck built before that pass existed.
  const intended = sizeForRole(theme, block.role);
  const plain = block.items?.length ? block.items.join(' ') : (block.text ?? '');
  const size = block.fontSize ?? intended * shrinkToFit(plain, box, intended);

  // Only meaningful in export mode, and only for an absolutely-positioned
  // element. A grid-placed element's row is `auto` height — it gets exactly
  // the room its text needs and there is nothing to shrink to fit.
  const minFontPx = (minSizeForRole(block.role) / 72) * EXPORT_PIXELS_PER_INCH;
  const flows = Boolean(gridArea) || inStack;
  const needsShrinkToFitProbe = viewportMode === 'export' && !flows;

  const typography: React.CSSProperties = {
    fontFamily: fontStack(theme, isHeading(block.role) ? 'heading' : 'body'),
    fontSize: pt(size),
    fontWeight: isHeading(block.role) ? 700 : 400,
    // The intended colour, unless it would be unreadable on what is behind it.
    color: readableOn(block.color ?? colorForRole(theme, block.role), behind, theme),
    lineHeight: 1.25,
    textAlign: align,
  };

  switch (block.type) {
    case 'image':
      // A dropped illustration renders as nothing rather than as a broken-image
      // icon: the .pptx it mirrors simply has no picture there either.
      return block.videoUrl ? (
        <video
          data-element-id={elementId}
          {...motion?.attrs}
          src={block.videoUrl}
          poster={block.imageUrl ?? undefined}
          aria-label={block.imagePrompt ?? ''}
          autoPlay
          loop
          muted
          playsInline
          style={{ ...frame, objectFit: 'cover', ...motion?.style }}
        />
      ) : block.imageUrl ? (
        <img
          data-element-id={elementId}
          {...motion?.attrs}
          src={block.imageUrl}
          alt={block.imagePrompt ?? ''}
          style={{ ...frame, objectFit: 'cover', ...motion?.style }}
        />
      ) : null;

    case 'card':
    case 'shape': {
      // A card's content is `text` OR `items`. Reading only `text` drew an
      // empty box for every card a designer filled with bullets — mirrored
      // here from the builder, where the same omission had the same effect.
      const single = block.items?.length === 1;

      return (
        <div
          data-element-id={elementId}
          data-min-font-px={needsShrinkToFitProbe ? minFontPx : undefined}
          {...motion?.attrs}
          style={{
            ...frame,
            ...motion?.style,
            background: block.fill ?? theme.colors.surface,
            border: `1px solid ${theme.colors.border}`,
            borderRadius: inches(0.12),
            display: 'flex',
            flexDirection: 'column',
            justifyContent: JUSTIFY[valign],
            // `margin: 6` (points) on the builder's side of this.
            padding: pt(6),
            overflow: 'hidden',
            ...typography,
            color: readableOn(
              block.color ?? theme.colors.text,
              block.fill ?? theme.colors.surface,
              theme,
            ),
          }}
        >
          {block.items?.length ? (
            single ? (
              // One item is a label, not a list.
              <p style={{ margin: 0 }}>{block.items[0]}</p>
            ) : (
              <ul
                style={{
                  margin: 0,
                  paddingLeft: inches(0.2),
                  display: 'flex',
                  flexDirection: 'column',
                  gap: inches(theme.spacing.paragraphGap),
                  listStyle: 'disc',
                  listStylePosition: 'outside',
                }}
              >
                {block.items.map((item, index) => (
                  <li key={index}>{item}</li>
                ))}
              </ul>
            )
          ) : (
            block.text
          )}
        </div>
      );
    }

    case 'divider':
      return (
        <div
          data-element-id={elementId}
          {...motion?.attrs}
          style={{
            ...frame,
            ...motion?.style,
            borderTop: `1px solid ${theme.colors.border}`,
            height: 0,
          }}
        />
      );

    default: {
      // text, statistic, diagram, chart — all render their words. The builder
      // does the same for the last two rather than dropping them silently.
      const gap = inches(theme.spacing.paragraphGap);

      // Same panel the builder lays down, for the same reason.
      const scrimmed = overText(block, slide);

      return (
        <div
          data-element-id={elementId}
          data-min-font-px={needsShrinkToFitProbe ? minFontPx : undefined}
          {...motion?.attrs}
          style={{
            ...frame,
            ...motion?.style,
            ...typography,
            display: 'flex',
            flexDirection: 'column',
            justifyContent: JUSTIFY[valign],
            // Live mode: the box is a floor, not a ceiling. `shrinkToFit` works
            // from an estimate — there is no font-metrics engine here — so it
            // is occasionally a hair optimistic, and clipping to the box turns
            // that into a heading that silently loses its last word. Letting
            // the text run on is both truthful and what PowerPoint does with
            // the same spec: a text box there overflows visibly too.
            //
            // Export mode, absolutely positioned: the box must stay a real
            // CEILING instead, fixed at `frame.height` with overflow left
            // visible — that is what lets `browser-layout.ts` detect overflow
            // at all (`scrollHeight > clientHeight`) and run its shrink-to-fit
            // loop against it. Export mode, grid-placed: no ceiling at all —
            // the row is `auto` height and grows to the text, which is the
            // point of using a grid here.
            ...(needsShrinkToFitProbe
              ? { height: frame.height, overflow: 'visible' }
              : flows
                ? { height: 'auto' }
                : { height: 'auto', minHeight: frame.height }),
            ...(scrimmed
              ? {
                  background: withAlpha(theme.colors.background, TEXT_SCRIM_OPACITY),
                  borderRadius: inches(0.08),
                }
              : {}),
          }}
        >
          {block.items?.length ? (
            <ul
              style={{
                margin: 0,
                // Bullets are drawn outside the text column, so the column
                // itself still starts on the box's left edge — matching the
                // way PowerPoint indents a bulleted paragraph.
                paddingLeft: inches(0.22),
                display: 'flex',
                flexDirection: 'column',
                gap,
                listStyle: 'disc',
                listStylePosition: 'outside',
              }}
            >
              {block.items.map((item, index) => (
                <li key={index}>{item}</li>
              ))}
            </ul>
          ) : (
            <p style={{ margin: 0 }}>{block.text}</p>
          )}
        </div>
      );
    }
  }
}

export function SlideCanvas({
  slide,
  theme,
  slideSize,
  className,
  viewportMode = 'live',
  animate = false,
}: SlideCanvasProps) {
  // Never in export mode — see the prop's comment. One place to enforce it,
  // rather than trusting every caller to remember.
  const motionOn = animate && viewportMode === 'live';
  // Same order the builder adds them in, for the same reason: a label belongs
  // on top of the card it names. `elementId` stays each block's ORIGINAL index
  // (not its position after this sort), because `browser-layout.ts` writes
  // measurements back onto `SlideElement[]` by that original index.
  const withId = slide.blocks.map((block, elementId) => ({ block, elementId }));

  // Grid placement only applies in export mode, to elements whose `slot` the
  // archetype's grid actually names — an unslotted element (or every element,
  // when there is no archetype) keeps the absolute `box` path unchanged.
  const grid =
    viewportMode === 'export' && slide.archetype ? ARCHETYPE_GRIDS[slide.archetype] : null;
  const gridAreaNames = grid ? new Set(grid.areas.join(' ').split(/\s+/)) : null;

  const floatEntries = grid
    ? withId.filter(({ block }) => block.slot && grid.floatSlots?.includes(block.slot))
    : [];
  const gridEntries = grid
    ? withId.filter(
        ({ block }) =>
          block.slot && gridAreaNames?.has(block.slot) && !grid.floatSlots?.includes(block.slot),
      )
    : [];
  // More than one element may legitimately claim a slot — the Slide Designer
  // is asked for a sub-heading above each group of bullets, so `col-1` often
  // holds a label and a list. Two children of the SAME grid area share one
  // cell and draw on top of each other, so a shared slot becomes one flex
  // column that owns the area and stacks its members inside it.
  const gridStacks = new Map<string, typeof gridEntries>();
  for (const entry of gridEntries) {
    const slot = entry.block.slot as string;
    const stack = gridStacks.get(slot);
    if (stack) stack.push(entry);
    else gridStacks.set(slot, [entry]);
  }

  const floatAndGridIds = new Set([...floatEntries, ...gridEntries].map((e) => e.elementId));
  const ordered = withId
    .filter(({ elementId }) => !floatAndGridIds.has(elementId))
    .sort((a, b) => layer(a.block) - layer(b.block));

  const marginPx = theme.spacing.outerMargin * EXPORT_PIXELS_PER_INCH;
  const gapPx = theme.spacing.sectionGap * EXPORT_PIXELS_PER_INCH;
  const slideWidthPx = slideSize.width * EXPORT_PIXELS_PER_INCH;
  const contentWidthPx = slideWidthPx - marginPx * 2;
  const panelWidthPx = grid?.widthFraction ? contentWidthPx * grid.widthFraction : null;

  const gridWrapperStyle: React.CSSProperties | null = grid
    ? {
        position: 'absolute',
        display: 'grid',
        gridTemplateColumns: grid.columns,
        gridTemplateRows: grid.rows,
        gridTemplateAreas: grid.areas.map((row) => `"${row}"`).join(' '),
        columnGap: gapPx,
        rowGap: gapPx,
        ...(panelWidthPx
          ? {
              width: panelWidthPx,
              left: grid.justifyContent === 'center' ? (slideWidthPx - panelWidthPx) / 2 : marginPx,
              ...(grid.alignContent === 'end'
                ? { bottom: marginPx }
                : grid.alignContent === 'center'
                  ? { top: '50%', transform: 'translateY(-50%)' }
                  : { top: marginPx }),
            }
          : {
              left: marginPx,
              top: marginPx,
              right: marginPx,
              bottom: marginPx,
              alignContent: grid.alignContent ?? 'stretch',
            }),
      }
    : null;

  return (
    <div
      className={className}
      data-motion-play={motionOn ? 'on' : undefined}
      style={{
        position: 'relative',
        aspectRatio: `${slideSize.width} / ${slideSize.height}`,
        width: '100%',
        overflow: 'hidden',
        background: theme.colors.background,
        // Everything inside sizes off this box, which is what lets the same
        // component be a thumbnail and a full-bleed stage.
        containerType: 'inline-size',
      }}
    >
      {slide.backgroundUrl ? (
        <>
          <img
            src={slide.backgroundUrl}
            alt=""
            style={{
              position: 'absolute',
              inset: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
            }}
          />
          {/* The scrim. Without it the deck's own text loses contrast against
              whatever the backdrop happens to be doing behind it — the same
              reason the builder lays a translucent rect over its backdrops. */}
          <div
            style={{
              position: 'absolute',
              inset: 0,
              background: theme.colors.background,
              opacity: slide.backgroundDim,
            }}
          />
        </>
      ) : null}

      {/* `full-bleed`'s picture: a layer behind the grid, not a grid cell —
          the text sits ON it, rather than beside it in its own area. */}
      {floatEntries.map(({ block, elementId }) =>
        block.videoUrl ? (
          <video
            key={elementId}
            data-element-id={elementId}
            src={block.videoUrl}
            poster={block.imageUrl ?? undefined}
            aria-label={block.imagePrompt ?? ''}
            autoPlay
            loop
            muted
            playsInline
            style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }}
          />
        ) : block.imageUrl ? (
          <img
            key={elementId}
            data-element-id={elementId}
            src={block.imageUrl}
            alt={block.imagePrompt ?? ''}
            style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }}
          />
        ) : null,
      )}

      {gridWrapperStyle ? (
        <div style={gridWrapperStyle}>
          {[...gridStacks].map(([slot, entries]) =>
            entries.length === 1 ? (
              <Block
                key={entries[0].elementId}
                block={entries[0].block}
                slide={slide}
                theme={theme}
                slideSize={slideSize}
                viewportMode={viewportMode}
                elementId={entries[0].elementId}
                gridArea={slot}
                animate={motionOn}
              />
            ) : (
              <div
                key={slot}
                style={{
                  gridArea: slot,
                  display: 'flex',
                  flexDirection: 'column',
                  gap: theme.spacing.elementGap * EXPORT_PIXELS_PER_INCH,
                  // Without this a long unbroken word makes the column wider
                  // than its track and pushes its neighbour off the slide.
                  minWidth: 0,
                }}
              >
                {entries.map(({ block, elementId }) => (
                  <Block
                    key={elementId}
                    block={block}
                    slide={slide}
                    theme={theme}
                    slideSize={slideSize}
                    viewportMode={viewportMode}
                    elementId={elementId}
                    inStack
                    animate={motionOn}
                  />
                ))}
              </div>
            ),
          )}
        </div>
      ) : null}

      {ordered.map(({ block, elementId }) => (
        <Block
          key={elementId}
          block={block}
          slide={slide}
          theme={theme}
          slideSize={slideSize}
          viewportMode={viewportMode}
          elementId={elementId}
          animate={motionOn}
        />
      ))}
    </div>
  );
}
